args.newString:
import { Playfair_Display, Roboto } from 'next/font/google';

const playfair = Playfair_Display({ subsets: ['latin'] });
const roboto = Roboto({ 
  weight: ['400', '700'],
  subsets: ['latin'] 
});

export default function BlogHeader() {
  return (
    <header>
      <h1 className={playfair.className}>My Personal Blog</h1>
      <p className={roboto.className}>Thoughts, ideas, and musings</p>
    </header>
  );
}

